import { createChange, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

type LightboxIndexChangeReason = "item-press" | "list-navigation" | "imperative"

type LightboxOptions = {
  index?: number
  count?: number
  onIndexChange?: (index: number, details: ChangeDetails<LightboxIndexChangeReason>) => void
  /** The items as agents see them: `{ value, label }`, value being the index as text. */
  entries?: readonly { value: string; label: string }[]
}

function reasonOf(options: unknown): { reason: LightboxIndexChangeReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<LightboxIndexChangeReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

function isRtl(element: Element) {
  return getComputedStyle(element).direction === "rtl"
}

const lightbox = definePrimitive({
  name: "lightbox",
  options: { index: "number", count: "number", onIndexChange: "callback", entries: "value" },
  controlled: ["index"],
  state: (options: LightboxOptions) => ({ index: options.index ?? 0, count: options.count ?? 0 }),
  sync: (options) => ({
    ...(options.index === undefined ? {} : { index: options.index }),
    ...(options.count === undefined ? {} : { count: options.count }),
  }),
  api: (context) => {
    const change = createChange(context)
    const move = (index: number, options: unknown) => {
      const { count, index: current } = context.store.get()
      if (index < 0 || index >= count || index === current) return false
      return change("index", index, reasonOf(options))
    }
    return {
      // The agent bridge passes arguments unchecked, and items list the index as text.
      goTo(index: unknown, options?: ChangeOptions<LightboxIndexChangeReason>) {
        const target = typeof index === "string" && index.trim() !== "" ? Number(index) : index
        const { count } = context.store.get()
        if (typeof target !== "number" || !Number.isInteger(target) || target < 0 || target >= count) {
          throw new RangeError(`goTo takes an index from 0 to ${count - 1}.`)
        }
        return move(target, options)
      },
      next: (options?: ChangeOptions<LightboxIndexChangeReason>) => move(context.store.get().index + 1, options),
      previous: (options?: ChangeOptions<LightboxIndexChangeReason>) => move(context.store.get().index - 1, options),
      entries: () => context.options().entries ?? [],
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({
        "data-first": state.index <= 0 ? "" : undefined,
        "data-last": state.index >= state.count - 1 ? "" : undefined,
      }),
      on: {
        keydown: (event, { api }) => {
          const keyboard = event as KeyboardEvent
          if (keyboard.defaultPrevented || keyboard.altKey || keyboard.ctrlKey || keyboard.metaKey) return
          if (keyboard.key !== "ArrowLeft" && keyboard.key !== "ArrowRight") return
          const target = keyboard.currentTarget as Element
          const forward = (keyboard.key === "ArrowRight") !== isRtl(target)
          const options = { reason: "list-navigation" as const, event: keyboard }
          if (forward ? api.next(options) : api.previous(options)) keyboard.preventDefault()
        },
      },
    }),
  }),
  agent: { actions: ["next", "previous", "goTo"], items: (api) => api.entries() },
})

export { lightbox }
export type { LightboxIndexChangeReason, LightboxOptions }

import type { ImgHTMLAttributes } from "react"

import { cn } from "@/lib/utils"

// The theme's dark rule, spelled out: `.dark` on an ancestor, or the system preference unless the page opted out.
// A consumer's `dark:` variant may only follow `.dark`, so these don't rely on it.
const lightOnlyClassName =
  "[:where(.dark)_&]:hidden [@media(prefers-color-scheme:dark)]:[:root:not(.light,[data-color-scheme=light])_&]:hidden"
const darkOnlyClassName =
  "hidden [:where(.dark)_&]:block [@media(prefers-color-scheme:dark)]:[:root:not(.light,[data-color-scheme=light])_&]:block"

/**
 * Pass `width` and `height` (the image's own size, in pixels): with the theme's `height: auto` the box is reserved at
 * that ratio before the image loads, so nothing below it moves when it arrives.
 */
type ThemedImageProps = Omit<ImgHTMLAttributes<HTMLImageElement>, "src"> & {
  src: string
  /** Shown instead of `src` while the page is dark. Both are rendered and CSS picks one, so nothing flashes. */
  srcDark?: string
}

function ThemedImage({ src, srcDark, className, alt = "", ...props }: ThemedImageProps) {
  if (!srcDark || srcDark === src) {
    return <img data-slot="themed-image" src={src} alt={alt} className={className} {...props} />
  }
  return (
    <>
      <img
        data-slot="themed-image"
        data-scheme="light"
        src={src}
        alt={alt}
        className={cn("block", className, lightOnlyClassName)}
        {...props}
      />
      <img
        data-slot="themed-image"
        data-scheme="dark"
        src={srcDark}
        alt={alt}
        className={cn(className, darkOnlyClassName)}
        {...props}
      />
    </>
  )
}

export { ThemedImage }
export type { ThemedImageProps }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { Button } from "@ui-sdk/react/button"
import { Dialog, DialogClose, DialogContent, DialogTitle } from "@ui-sdk/react/dialog"
import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { useMemo, useRef, useState, type ComponentProps, type ReactNode, type RefObject } from "react"
import { ChevronLeftIcon, ChevronRightIcon, ExternalLinkIcon, XIcon, ZoomInIcon } from "lucide-react"

import { buttonVariants } from "@/components/ui/button"
import { DialogBackdrop, dialogContentVariants } from "@/components/ui/dialog"
import { useVisualViewportBox } from "@/components/ui/use-dialog-viewport"
import { Link } from "@/components/ui/link"
import { lightbox, type LightboxIndexChangeReason } from "@/components/ui/lightbox-primitive"
import { ScrollArea, ScrollAreaCorner, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import { ThemedImage, type ThemedImageProps } from "@/components/ui/themed-image"
import { ControlTooltip } from "@/components/ui/tooltip"
import { Toggle } from "@/components/ui/toggle"
import { cn } from "@/lib/utils"

type LightboxItem = {
  id: string
  src: string
  srcDark?: string
  alt: string
  /** The caption's title; `alt` when absent. */
  name?: string
  /** The original to open in a new tab; `src` when absent. */
  href?: string
}

type LightboxLabels = {
  viewer: string
  previous: string
  next: string
  close: string
  actualSize: string
  openOriginal: string
  counter: (position: number, count: number) => string
}

const lightboxLabels: LightboxLabels = {
  viewer: "Image viewer",
  previous: "Previous image",
  next: "Next image",
  close: "Close viewer",
  actualSize: "Actual size",
  openOriginal: "Open original",
  counter: (position, count) => `${position} / ${count}`,
}

type IndexChange = (index: number, details: ChangeDetails<LightboxIndexChangeReason>) => void
type DialogProps = ComponentProps<typeof Dialog>

type LightboxProps = {
  items: readonly LightboxItem[]
  index?: number
  defaultIndex?: number
  onIndexChange?: IndexChange
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: DialogProps["onOpenChange"]
  controller?: DialogProps["controller"]
  /** Where focus goes on close; by default the trigger, or what was focused before it opened. */
  finalFocus?: ComponentProps<typeof DialogContent>["finalFocus"]
  labels?: Partial<LightboxLabels>
  className?: string
  /** A `DialogTrigger`, or anything else that belongs inside the dialog root. */
  children?: ReactNode
}

// oxlint-disable-next-line shadcn/require-static-classes -- the Button look, from buttonVariants, on a link
const iconButtonClassName = cn(buttonVariants({ variant: "ghost", size: "icon" }), "shrink-0")
const stepClassName = cn(
  buttonVariants({ variant: "outline", size: "icon" }),
  "absolute inset-y-0 z-10 my-auto rounded-full bg-popover/(--glass-opacity) shadow-floating data-disabled:hidden",
)

type ViewProps = {
  items: readonly LightboxItem[]
  index: number
  onIndexChange: IndexChange
  labels: LightboxLabels
}

function LightboxView({ items, index, onIndexChange, labels }: ViewProps) {
  const count = items.length
  const item = items[index]!
  const entries = useMemo(
    () => items.map((entry, position) => ({ value: String(position), label: entry.name ?? entry.alt })),
    [items],
  )
  const handle = usePrimitive(lightbox, { index, count, entries, onIndexChange })
  const [zoom, setZoom] = useState<{ id: string; actual: boolean }>()
  const actual = zoom?.id === item.id && zoom.actual

  const children = (
    <>
      <div
        data-slot="lightbox-header"
        className="flex min-w-0 items-center gap-items border-b px-inset-item py-inset-item"
      >
        <DialogTitle className="min-w-0 flex-1 truncate text-title-sm">{item.name ?? item.alt}</DialogTitle>
        {count > 1 && (
          <span
            data-slot="lightbox-counter"
            aria-live="polite"
            className="shrink-0 text-caption text-muted-foreground tabular-nums"
          >
            {labels.counter(index + 1, count)}
          </span>
        )}
        <Toggle
          size="icon"
          aria-label={labels.actualSize}
          pressed={actual}
          onPressedChange={(pressed) => setZoom({ id: item.id, actual: pressed })}
        >
          <ZoomInIcon />
        </Toggle>
        <ControlTooltip label={labels.openOriginal}>
          <Link
            data-slot="lightbox-original"
            variant="plain"
            href={item.href ?? item.src}
            target="_blank"
            rel="noreferrer"
            aria-label={labels.openOriginal}
            className={iconButtonClassName}
          >
            <ExternalLinkIcon />
          </Link>
        </ControlTooltip>
        <ControlTooltip label={labels.close}>
          <DialogClose aria-label={labels.close} className={iconButtonClassName}>
            <XIcon />
          </DialogClose>
        </ControlTooltip>
      </div>
      <div data-slot="lightbox-stage" className="relative min-h-0 flex-1 bg-muted/(--glass-opacity)">
        <ScrollArea className="absolute! inset-0">
          <ScrollAreaViewport
            data-zoom={actual ? "actual" : "fit"}
            className="grid place-items-center-safe p-group"
            render={(part) => <div {...part} data-slot="lightbox-viewport" />}
          >
            <ThemedImage
              key={item.id}
              src={item.src}
              srcDark={item.srcDark}
              alt={item.alt}
              decoding="async"
              className={cn("rounded-control", actual ? "max-w-none" : "max-h-full max-w-full object-contain")}
            />
          </ScrollAreaViewport>
          <ScrollAreaScrollbar data-agent-hidden="" />
          <ScrollAreaScrollbar orientation="horizontal" data-agent-hidden="" />
          <ScrollAreaCorner />
        </ScrollArea>
        {count > 1 && (
          <>
            <ControlTooltip label={labels.previous}>
              <Button
                aria-label={labels.previous}
                disabled={index === 0}
                focusableWhenDisabled
                onClick={(event) => handle.api.previous({ reason: "item-press", event: event.nativeEvent })}
                className={cn(stepClassName, "start-group")}
              >
                <ChevronLeftIcon className="rtl:rotate-180" />
              </Button>
            </ControlTooltip>
            <ControlTooltip label={labels.next}>
              <Button
                aria-label={labels.next}
                disabled={index === count - 1}
                focusableWhenDisabled
                onClick={(event) => handle.api.next({ reason: "item-press", event: event.nativeEvent })}
                className={cn(stepClassName, "end-group")}
              >
                <ChevronRightIcon className="rtl:rotate-180" />
              </Button>
            </ControlTooltip>
          </>
        )}
      </div>
      {item.name && item.alt !== item.name && (
        <p
          data-slot="lightbox-caption"
          className="border-t px-inset-item py-inset-item text-body-sm text-muted-foreground"
        >
          {item.alt}
        </p>
      )}
    </>
  )

  return usePart(
    handle,
    "root",
    {},
    { "aria-label": labels.viewer, className: "flex min-h-0 flex-1 flex-col", children },
    "div",
  )
}

// Mounts with the content, so the content sits in the part of the page you can see, as a DialogContent does.
function ViewportBox({ contentRef }: { contentRef: RefObject<HTMLElement | null> }) {
  useVisualViewportBox(contentRef)
  return null
}

function Lightbox({
  items,
  index: indexProp,
  defaultIndex = 0,
  onIndexChange,
  open,
  defaultOpen,
  onOpenChange,
  controller,
  finalFocus,
  labels,
  className,
  children,
}: LightboxProps) {
  const [ownIndex, setOwnIndex] = useState(defaultIndex)
  const index = Math.min(Math.max(indexProp ?? ownIndex, 0), Math.max(items.length - 1, 0))
  const contentRef = useRef<HTMLDivElement | null>(null)

  return (
    <Dialog open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange} controller={controller}>
      {children}
      <DialogBackdrop />
      <DialogContent
        ref={contentRef}
        finalFocus={finalFocus}
        render={<div data-slot="lightbox" />}
        // Never a bottom sheet: a sheet fits its content, and the image stage has no height of its own.
        className={cn(
          dialogContentVariants({ size: "full", sheet: false }),
          "max-w-6xl gap-0 overflow-hidden p-0",
          className,
        )}
      >
        {items.length > 0 && (
          <LightboxView
            items={items}
            index={index}
            labels={{ ...lightboxLabels, ...labels }}
            onIndexChange={(next, details) => {
              onIndexChange?.(next, details)
              if (!details.canceled) setOwnIndex(next)
            }}
          />
        )}
        <ViewportBox contentRef={contentRef} />
      </DialogContent>
    </Dialog>
  )
}

export { Lightbox, lightboxLabels }
export { ThemedImage }
export type { LightboxItem, LightboxLabels, LightboxProps }
export type { ThemedImageProps }
